    if(form){const copy=duplicatePool(runConfig(doc),id,form.name);await mutate(()=>{doc.config=copy.config;selected=copy.id;activeBanner(doc).collapsed=activeBanner(doc).collapsed.filter(x=>x!==parent.id);});}
